#   「劇本大綱明確了 2035 年南京，劇本名字就是外賣員，世界觀第一句就是『全鏈智能』AI 系統上線，
#     他出來的是 80 年代的破街爛車，人物也搞得像個協警，和外賣員的特徵沒有關係」
#   「人物年齡，人物身材比例都卡不到」
