# ---- 運鏡門 C18g~l 常量（short-drama-camera-system.md §四 · 2026-10-10 新增）----
# 病因：§四 的運鏡約束此前**零機檢載體**——運鏡詞只出現在已下線專線的剝離詞表（用來把運鏡詞
