# ---- C17 擺位必入畫（model-adapters §5.0.1 人物賬連續）----
# ★內部 ID 前綴兼容（2026-10-12 修復）：包內 12 個規範文件（model-adapters / seedance-render-engine /
#   acting-direction / production-ledger-handbook 等）的示例長期寫成 `@CHR-老周` /
#   `@SCN-地下拳房` 編號式，而鏡行正文按慣例用簡稱「老周」。原正則把 `CHR-老周` 整體捕獲，
#   與鏡行簡稱永遠匹配不上 → C17 擺位必入畫 / C17b 關係鏡 / C17c 背景錨點 / C17d 跨段漂移 /
#   C19c 首鏡主體優先 **五條判據對編號式稿件全體誤報**（實測 歷史示例稿 連報 4 條）。
#   前綴列為非捕獲組，group(1) 恆為裸人名；`@老周` 純淨式不受影響。
#   ⚠️ 注意：`asset-delivery-modes.md` 紅線 11 明令「接線單不寫內部 ID」——本兼容只為讓機檢
#   不誤傷存量示例，**不構成對編號式寫法的認可**，新稿仍應寫 `@人名`。
ZW_PERSON_RE = re.compile(r"@(?:(?:CHR|SCN|PRP|ITM|PROP|ENV|OBJ)-)?([^\s@（）()【】，、；;：:]+)")
C17_EXIT_WORDS = ("離畫", "退場", "離場", "出畫", "未入鏡", "不入鏡")

# ★站位人物寬鬆兜底解析（2026-10-11 新增 · 與 C7c 元檢查配套）：
# 病根：規範格式是 `@人名（畫面右 · …）`，但實跑稿常寫成 `A（畫面右 · …）`（漏 `@`）——
# 此時 ZW_PERSON_RE 解析為空，C17 擺位必入畫 / C17b 關係鏡 / C17c 背景錨點 /
# C17d 跨段站位漂移 / C19c 首鏡主體優先 **五條判據整體靜默失效**，腳本卻照打 PASSED。
# 兜底：按 `、；;` 切 token，剝掉【站位聲明】前綴後要求「名（」緊鄰——寬鬆，但不會把
# 「位移：C 自身後門邊…（畫面左後）」這類從句誤認成人名（名後若跟 `：` 或長串即失配）。
_ZW_LOOSE_HEAD = re.compile(r"^(?![@【])([^\s（(【】：:]{1,14})\s*[（(]")


def _zw_people_loose(block):
    """寬鬆解析站位聲明人物名（僅在 `@` 式解析為空時兜底調用）。"""
    out = []
    for tok in re.split(r"[、；;]", block or ""):
        t = re.sub(r"^\s*【站位聲明】\s*[：:]\s*", "", tok.strip())
        m = _ZW_LOOSE_HEAD.match(t)
        if m:
            name = m.group(1).strip()
            if name and name not in out:
                out.append(name)
    return out

