# ---- C32 畫面段最低三要素（2026-10-16 新增 · 治「畫面提示詞沒有背景描述」）----
# 病根：shot-economy-and-acting.md §九 早就寫了「畫面描述必須包含…背景元素」，但**全腳本零斷言**
