#   同 §一 特寫區間 2026-10-13 的歷史教訓：**只寫不檢 = 不生效**。
# 判據：鏡行「畫面段」（`台詞：` 之前的部分）須同時含 ② 背景元素 ③ 光線方向。
# ★ 編號說明：本包 C30 已用於「外掛指紋與跨階段交接探針」（2026-10-14），故本碼取 C32（編號不重排）。
