    r"陳設|傢俱|牆面|地面|屋頂|天空|街|巷|路|河|橋|山|"
    # ★2026-10-16 擴詞：原表只有「樹花草石」數項，實測明確的**背景環境行為**被漏判（假 WARN）——
    #   例：「腳下泥土犁出兩道淺溝，竹葉被氣浪掀飛」中「泥土」「竹葉」全不在表內 → 判成"無背景"。
    #   補 ① 自然環境元素 ② 環境行為（背景"活著"的證據）。
    r"竹|葉|枝|藤|苔|泥|土|沙|溪|泉|水|露|霜|林|木|坡|崖|谷|籬|簷|渠|溝|灰|燼|"
