# C19 禁令失效三改法（model-adapters §5.0.4）：視頻模型對否定不敏感、對詞根敏感——
# 「禁空鏡」裡的空鏡、「不發光」裡的發光、「面無笑意」裡的笑，被禁概念的詞根本身留在提示詞裡
# 等於把畫面詞餵給了模型（實測三條禁令全部被無視）。高關聯視覺概念必須在鏡行內做正向描寫。
