# C19d 具象光源映射汙染：「玉面映出油燈火苗」——模型不理解"反射"，
# 會把「映出+光源名詞」讀成"光源出現在道具上"（玉面畫小火苗/整體泛光）。改寫為光斑語言。
FLAME_MAP_RE = re.compile(r"(映出|倒映|映著|反射出)[^。；]*?(火苗|火焰|燈火|燭火)")
# C20d 道具光效描寫歸零：的"光斑語言"（受油燈照射處
# 只有指甲蓋大一片暖黃光斑）實測仍被渲染成玉佩點火（用戶：「玉佩上面像個打火機，點了一簇火」）
# ——道具只要與光/火產生描寫關聯（光斑/受光/照射/照在/亮起）或動作上貼近光源（舉到油燈旁），
# 模型就可能給它點火。唯一正解：反光道具**零光效描寫**，只寫材質本色（青玉原色/啞光金屬本色）。
PROP_LIGHT_RE = re.compile(r"光斑|受光|受[^。；]{0,8}照射|照射|照在|亮起")
LAMP_NEAR_RE = re.compile(r"(舉|湊|貼|送|遞)[^。；]{0,6}(到|向|至)[^。；]{0,8}(油燈|燈|燭|火)")
# C19e 禁止項欄目紀律（model-adapters §5.0.4）：
# 【強制禁止項】被模型當"規避清單"讀，只裝負面項。正向執行指令（首幀/材質/表情/姿態/視線）寫進去
# 兩頭不生效（既不被當禁令，也不被當執行指令）——實測「全片首幀即鏡1的人物近景畫面」
# 「道具保持日常石質與金屬質感」等同廢紙；否定式禁令（不發光/面無笑意）同理失效（C19e-b）。
C19E_POS_RE = re.compile(
    r"(即[^。；]{0,24}?(畫面|鏡頭|首幀)|保持[^。；]{0,14}?(質感|狀態|位置|本色)|必須|應寫出|應寫明|寫明|複述|畫面主體|以.{1,10}為主|呈[^。；]{0,10}?(色|質|感))")
C19E_NEG_WORDS = ("禁止", "禁", "無", "不", "防", "杜絕", "避免", "杜絕")

# C20 首鏡單主體錨定 + 抽象形容（model-adapters §5.0.2/§5.0.4）：
# 病灶實測（「重生70」EP01 段1 鏡1 出片**兩張臉**）：鏡行寫「首幀即這隻手與她的臉同框」——
# 「手」與「臉」被寫成**並列名詞**，疊加「同框」這個多主體觸發詞 → 模型讀成兩個主體，
# 渲染出兩個頭/兩張臉（用戶拉片："總共生成了兩張臉，最大的禍首就是這兒"）。
# 正解：首鏡錨定句只由**一個具名主體**統攝，身體部位一律以「她的/其+部位」從屬出現。
MULTI_SUBJ_RE = re.compile(r"同框|同在畫面|一同入畫|同時入畫|與[^。；，]{1,8}同(處|在|入)")
