# ---- C21 打戲激烈度硬護欄（sd-combat-engine/references/combat-intensity-guardrails.md §二）----
# 實測病徵：出片後逐幀看，每 2~3 秒只有一個靜態構圖（對峙→特效→對峙→特效），全程零貼身對招。
# 根因：時碼分段沒強制"同一區間內必須有位移與接觸"，模型把每段理解成一張畫。
# ⚠️ 本組**只對打戲稿生效**：文戲稿不跑（防誤報拖垮整包機檢可信度）。
