COMBAT_FULL_SIZE = ("中全景", "中景", "全景", "大遠景")
COMBAT_TIGHT_SIZE = ("特寫", "近景", "中近景")
COMBAT_TIGHT_MAX_RUN = 2          # 貼臉檔連續上限
# ★ 結構標註剝離：只剝離 ≤6 字的純結構標籤，**不得連坐含實寫正文的括號塊**
#   （構建期實測：貪婪寫法 `（[^）]*(?:拍|幀)[^）]*）` 會把
#    「（命中瞬間畫面頓住兩幀，命中點炸開一圈衝擊波）」整塊吃掉 → 鏡頭4 明明寫了頓幀卻誤報缺失。）
COMBAT_STRUCT_TAGS = frozenset((
    "起手拍，慢", "爆發拍，快", "頓幀", "收勢拍，慢", "轉折",
    "起手拍", "爆發拍", "收勢拍", "假動作", "戰術變化",
))
# ★ 讓行條款（2026-10-12 用戶裁定 · 勿刪）：C21/C22 是 **WARN 參考**，不是一票否決——
#   判據原型取自「現代近身肉搏」單樣本，不外推為全戲型法規；打戲檔（R1/R2/R3）領域規則
#   以打戲引擎本檔為準。現場景按豁免表放行（R1 槍戰/狙擊/暗殺/追車/兒童向、近景機槍對招段，
#   R3 大場面檔/術法對轟·遠程檔，群戰亂鬥）。豁免表唯一權威 =
#   sd-combat-engine/references/combat-rhythm-and-load-guardrails.md §七（+ combat-intensity-guardrails.md §六）。
#   ⛔ 禁止為消除 C21/C22 告警而把打戲改呆（拆招式序列 / 近景對招拉遠景 / 每鏡硬塞慢動作）。
COMBAT_EGRESS = ("〔參考·打戲檔可豁免：R1 槍戰/狙擊/暗殺/追車/兒童向 · R3 大場面/術法對轟 · 群戰亂鬥 "
                 "按 combat-rhythm-and-load-guardrails.md §七 放行，非一票否決〕")


def _strip_struct_annot(s):
    """剔除純結構標註（給人看的標籤），保留含實寫正文的括號塊。

    ⚠️ 構建期踩坑二：單純用「≤6 字且不含逗號」當標籤，會把
    `（咬牙·悶哼）` 這類**台詞語氣說明**誤刪——它雖短，但屬正文。
    正法：白名單命中才剝；非白名單一律保留（寧可漏剝，不可誤刪正文造成假陰性）。
    """
    def _rep(m):
        inner = m.group(0)[1:-1].strip()
        return "" if inner in COMBAT_STRUCT_TAGS else m.group(0)
    return re.sub(r"（([^）]*)）", _rep, s)


def _combat_iau(pic):
    """統計一個鏡行的獨立動作單元（IAU）數：同一次接觸的多寫只算 1 個。

    ⚠️ 構建期踩坑：「抓住腳踝」既在主表裡、又被賓語規則二次計數，
    set 去重後計數反而錯亂（實測「一爪抓住劍修腳踝」計 0 個）。
    正法：主表命中即計 1，不再疊加賓語規則；賓語正則只用於主表未覆蓋的裸「抓住」。
    """
    _hits = set(COMBAT_IAU_RE.findall(pic))
    _n = len(_hits)
    # 主表未命中任何帶賓語的「抓住」時，才用賓語規則補 1
    if not any(h.startswith("抓住") for h in _hits) and COMBAT_IAU_GRAB_RE.search(pic):
        _n += 1
    return _n


def _combat_tactic_types(pic):
    """該鏡行覆蓋了幾類動作技術（一鏡多任務判定用）。"""
    return [k for k, rx in COMBAT_TACTIC_TYPES.items() if rx.search(pic)]


def _iau_limit(dur_s):
    """按鏡長給 IAU 上限（§1.2）。3s 定為 2——超 2 個保質率驟降。"""
    if dur_s <= 2:
        return 2
    if dur_s <= 3.5:
        return 2
    if dur_s <= 4.5:
        return 3
    if dur_s <= 6:
        return 3
    return 4



def _combat_on(text, mode="auto"):
    """C21 觸發門：打戲稿才跑本組（文戲稿零誤報是底線）。"""
    if mode == "on":
        return True
    if mode == "off":
        return False
    return len(COMBAT_SIGNAL_RE.findall(text)) >= COMBAT_SIGNAL_MIN


def _pic_only(line):
    """剝掉「聲音：」之後的音效段——音效裡的"撞擊聲/交擊聲"會把接觸判據帶偏。"""
    si = line.find("聲音：")
    return line[:si] if si >= 0 else line


# C21 專用區間解析：**必須兼容打戲稿的整數秒格式**（`0-3秒` / `3-6秒`）。
# 注：2026-10-14 ◑15 已將 N-N秒（帶守衛+緊寫判別）併入總控 TIME_RE；C21 保留本解析器以兼容散行打戲草稿。
COMBAT_RANGE_RE = re.compile(
    r"(\d{1,2}):(\d{2})(?:[.:](\d{1,2}))?\s*[-~～→]\s*(\d{1,2}):(\d{2})(?:[.:](\d{1,2}))?"
    r"|(\d+(?:\.\d+)?)\s*s\s*[-~～→]\s*(\d+(?:\.\d+)?)\s*s"
    r"|(\d+(?:\.\d+)?)\s*[-~～→]\s*(\d+(?:\.\d+)?)\s*[秒sS]", re.I)


def _combat_ranges(text):
    """返回 [(start_s, end_s, line_no, 畫面段)]，按行聚合（一行 = 一個時間區間）。

    兩道過濾（防誤判）：
    ① **只認鏡行**：行首（剝掉列表符後）必須是數字時碼，或行內含 `[鏡頭N]`——
       說明文字行（如「三輪攻守：0-6 秒…」）會被誤聚合成一整段，必須排除；
    ② **重複拷貝去重**：稿件常同時含「分鏡稿 + 投餵稿」兩份同一時間軸，
       完全相同的 (起, 止, 畫面段) 只保留一份，防連續計數被翻倍稀釋。
    """
    out, seen = [], set()
    for i, line in enumerate(text.splitlines(), 1):
        probe = re.sub(r"^[\s\-*>•]+", "", line)
        if not (re.match(r"\d", probe) or SHOT_TAG_RE.search(line)):
            continue
        rs = []
        for m in COMBAT_RANGE_RE.finditer(line):
            if m.group(1) is not None:
                s = int(m.group(1)) * 60 + int(m.group(2)) + _frac_to_sec(m.group(3))
                e = int(m.group(4)) * 60 + int(m.group(5)) + _frac_to_sec(m.group(6))
            elif m.group(7) is not None:
                s, e = float(m.group(7)), float(m.group(8))
            else:
                s, e = float(m.group(9)), float(m.group(10))
            rs.append((round(s, 2), round(e, 2)))
        if not rs:
            continue
        seg = _pic_only(line)
        key = (min(x[0] for x in rs), max(x[1] for x in rs), seg.strip())
        if key in seen:
            continue
        seen.add(key)
        out.append((key[0], key[1], i, seg))
    return out


def _union_len(spans):
    """區間並集時長——稿件常同時含「分鏡稿 + 投餵稿」兩份時間軸（同一段時間被寫兩遍），
    直接 sum 會把片長算成 2~3 倍。取並集才是真實片長。"""
    if not spans:
        return 0.0
    spans = sorted(spans)
    total, cs, ce = 0.0, spans[0][0], spans[0][1]
    for s, e in spans[1:]:
        if s <= ce:
            ce = max(ce, e)
        else:
            total += ce - cs
            cs, ce = s, e
    return total + (ce - cs)


def parse_time_ranges(text):
    """返回 [(start_s, end_s, line_no)]，兼容 MM:SS(.ff) / Xs-Ys / N-N秒 三形態。

    ⚠️ 三形態與 TIME_RE 的分組一一對應（1-6 / 7-8 / 9-10）——加形態必須同步這裡，
    否則落到 `else` 分支做 `float(None)` 直接崩（2026-10-14 補 N-N秒 時同批處理）。
    """
    out = []
    for i, line in enumerate(text.splitlines(), 1):
        for m in TIME_RE.finditer(line):
            if m.group(1) is not None:
                s = int(m.group(1)) * 60 + int(m.group(2)) + _frac_to_sec(m.group(3))
                e = int(m.group(4)) * 60 + int(m.group(5)) + _frac_to_sec(m.group(6))
            elif m.group(7) is not None:
                s, e = float(m.group(7)), float(m.group(8))
            else:
                s, e = float(m.group(9)), float(m.group(10))
            out.append((round(s, 2), round(e, 2), i))
    return out


# ---- C23 畫風鎖機檢（references/style-bible/director-to-prompt-protocol.md §六）----
# 來源：審計工作區原型 c23_check.py（自檢三輪 loop 定稿），判據與實現保持一致。
# 觸發門 = --c23 on 強制 / off 關閉 / 默認 auto（稿內存在【STYLE/【PERFORMANCE 塊或
#          --style-source 登記來源即啟用——I 鎖未啟用的舊稿不追溯，零誤報）。

def _c23_on(text, mode="auto", style_source=None):
    """C23 觸發門：畫風鎖已啟用（段8/9 存在或來源已登記）才跑本組。"""
    if mode == "on":
        return True
    if mode == "off":
        return False
    return bool(re.search(r"(?m)^【STYLE", text)) or \
        bool(re.search(r"(?m)^【PERFORMANCE", text)) or bool(style_source)


# 區間聲明解析（段8/9 的 [lo, hi] 量化區間）
C23_NUM_RANGE  = re.compile(r"\[\s*\d+\s*[:：]\s*(\d+(?:\.\d+)?)\s*,\s*\d+\s*[:：]\s*(\d+(?:\.\d+)?)\s*\]")  # 光比 [1:6, 1:10]
C23_MM_RANGE   = re.compile(r"\[\s*(\d+)\s*mm\s*,\s*(\d+)\s*mm\s*\]")    # 鏡頭 [21mm, 28mm]
C23_FPS_RANGE  = re.compile(r"\[\s*(\d+)\s*fps\s*,\s*(\d+)\s*fps\s*\]")  # 幀率
C23_K_RANGE    = re.compile(r"\[\s*(\d+)\s*K\s*,\s*(\d+)\s*K\s*\]")      # 色溫
C23_PCT_RANGE  = re.compile(r"\[\s*(\d+)%\s*,\s*(\d+)%\s*\]")
C23_ENUM_RANGE = re.compile(r"\[\s*(低|中|高)\s*,\s*(低|中|高)\s*\]")
