#   否則打戲分鏡稿在畫風鎖下解析出 0 鏡，C23b/c/f 全線靜默失效。
# ★鏡號括號放寬（2026-10-11）：半角 `[鏡頭1]` / 全角 `【鏡頭1】` / 混寫 `【鏡頭1]` 均可，
#   否則 LLM 輸出全角鏡號時畫風鎖的 C23b/c/f 解析出 0 鏡 → 三項判據靜默失效。
C23_SHOT_LINE  = re.compile(
    r"(?m)^\s*(?:"
    r"(?:\d+(?:\.\d+)?(?:s|秒)?|\d{1,2}:\d{2})\s*[-~～→]\s*(?:\d+(?:\.\d+)?(?:s|秒)?|\d{1,2}:\d{2})\s*[\[【]?\s*(鏡頭\s*\d+)\s*[\]】]?"
    r"|[\[【]?\s*(鏡頭\s*\d+)\s*[\]】]?\s*[,，]?\s*(?:\d+(?:\.\d+)?(?:s|秒)?|\d{1,2}:\d{2})\s*[-~～→]\s*(?:\d+(?:\.\d+)?(?:s|秒)?|\d{1,2}:\d{2})"
    r")(.*)$")
C23_SHOT_LIGHT = re.compile(r"光比約?\s*1\s*[:：]\s*(\d+(?:\.\d+)?)")
C23_SHOT_LENS  = re.compile(r"(\d+)\s*mm")
C23_SHOT_FPS   = re.compile(r"(\d+)\s*fps")

