                   "3-8秒 [鏡頭2] 近景 · 側45度 · 緩推。@劍客 的手按上劍柄。聲音：無。台詞：無。\n"
                   "8-12秒 [鏡頭3] 特寫 · 側45度 · 定鏡。@劍客 的眼瞼繃緊。聲音：無。台詞：無。\n"
                   "12-25秒 [鏡頭4] 全景 · 平視 · 緩拉。@劍客 收劍入鞘。聲音：無。台詞：無。\n"
