    if not any(TIME_RE.search(l) for l in _t_bare_sec.splitlines()):
        print("FAIL self-test: N-N秒 稿應有時碼命中"); ok = 0

    # 70o) 2026-10-14 全鏈路閉環新增迴歸用例（C30a/b/c/d + C27 N-N秒 + 打戲逗號鏡行頭 C19c 不誤報 + 多段 C26/C29）
