    #   ①b 2026-10-14 Agent 修復迴歸鎖：默認 `--plugin auto` 下判出玄幻打戲檔，C30d 同樣必須核驗
    #       （原實現只認顯式 --plugin → auto 下整組 C30c/C30d 靜默不跑，與 SKILL.md 硬規形成空檔）
