    # 73) C18p 景別佔比越界（需 ≥10 鏡 · 六組歸併 · 文戲/打戲分檔）
    def _mk_shots(sizes):
        out, t = "", 0
        for i, sz in enumerate(sizes, 1):
            out += (f"00:{t:02d}-00:{t + 3:02d} [鏡頭{i}] {sz} · 平視 · 固定。"
                    "甲坐在桌旁，身後的木櫃影子落在牆上，窗光斜切進來。聲音：無。台詞：無。\n")
