    # ---- 75) C36/C37 連續動作拆解與背景多人同動（P5 新增 · 2026-10-22）----
    # 病根出處：blooper-prevention-playbook.md §一/§三（長鏡連續路徑一句帶過 + 群體動作未點名實測）
    # 注意：C35/C36/C37 實現在 finalize_checks（main 流程才跑），self-test 須直接調它——
